export interface GeneratedImage {
  id: string;
  dataUrl: string;
  base64?: string;
  sourceImageUrl?: string;
  prompt: string;
  chipLabel: string;
  modelName: string;
  timestamp: number;
  status: 'loading' | 'ready' | 'error';
}

export interface AngleChip {
  id: string;
  label: string;
  emoji: string;
  defaultPrompt: string;
}

export interface SourceImage {
  id: string;
  base64: string;
  dataUrl: string;
  mimeType: string;
}

import { AngleChip } from './types';

export const PRESET_ANGLES: AngleChip[] = [
  { 
    id: 'zoom-in',
    label: 'zoom in', 
    emoji: '🔍', 
    defaultPrompt: 'Zoom in closer to the main subject/area of this image, macrophotography detail.' 
  },
  { 
    id: 'zoom-out',
    label: 'zoom out', 
    emoji: '🔭', 
    defaultPrompt: 'zoom out to a very wide shot so I can see much more of surrounding environment.' 
  },
  { 
    id: 'pan-left',
    label: 'pan left', 
    emoji: '⬅️', 
    defaultPrompt: 'pan to the left to reveal new details of the scene' 
  },
  { 
    id: 'pan-right',
    label: 'pan right', 
    emoji: '➡️', 
    defaultPrompt: 'pan to the right to reveal new details of the scene' 
  },
  { 
    id: 'birds-eye',
    label: 'aerial shot', 
    emoji: '🦅', 
    defaultPrompt: 'give me an overhead aerial view. zoom out so you can see the entire scene, looking straight down on it, far away.' 
  },
  { 
    id: 'side-view',
    label: 'side view', 
    emoji: '📐', 
    defaultPrompt: 'Side profile view' 
  },
  { 
    id: 'extreme-detail',
    label: 'extreme detail', 
    emoji: '👁️', 
    defaultPrompt: 'give me an ultra close-up shot. zoom in extremely close to a specific detail of the main subject of this image, revealing incredible detail and texture, macrophotography.' 
  },
  { 
    id: 'back-view',
    label: 'back view', 
    emoji: '👤', 
    defaultPrompt: 'rotate the camera to show me the back of the main subject entity in this image. I want an entirely new perspective on the scene.' 
  },
  { 
    id: 'surprise-me',
    label: 'surprise me', 
    emoji: '🎲', 
    defaultPrompt: \"Pick any specific detail of this image and zoom in extremely close up to it, revealing its textures and details, macrophotography. Don't just pick the main subject/area, surprise me by choosing some other detail I may not notice.\" 
  }
];

import React, { useState } from 'react';
import { GeneratedImage } from '../types';
import { Download, RefreshCw, ChevronDown, ChevronUp, CheckCircle2, ArrowLeft, Trash2 } from 'lucide-react';

interface ImageCardProps {
  image: GeneratedImage;
  onReFire: (image: GeneratedImage) => void;
  onPromote: (image: GeneratedImage) => void;
  onDelete: (id: string) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ image, onReFire, onPromote, onDelete }) => {
  const [showFullPrompt, setShowFullPrompt] = useState(false);
  const [isSaved, setIsSaved] = useState(false);

  const handleDownload = async () => {
    if (image.status !== 'ready') return;
    try {
      const link = document.createElement('a');
      link.href = image.dataUrl;
      link.download = `shot-${Date.now()}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setIsSaved(true);
      setTimeout(() => setIsSaved(false), 2000);
    } catch (e) {
      console.error(e);
    }
  };

  const onDragStart = (e: React.DragEvent) => {
    if (image.status !== 'ready') return;
    e.dataTransfer.setData('application/json', JSON.stringify(image));
    e.dataTransfer.effectAllowed = 'move';
  };

  const isLoading = image.status === 'loading';

  return (
    <div 
      className={`flex flex-col w-full group ${image.status === 'ready' ? 'cursor-grab active:cursor-grabbing' : ''}`}
      draggable={image.status === 'ready'}
      onDragStart={onDragStart}
    >
      {/* Visual Container */}
      <div className=\"relative aspect-video border border-[rgba(218,220,224,0.15)] bg-[#0e0e0e] rounded-2xl overflow-hidden mb-4 shadow-sm transition-all\">
        {isLoading ? (
          <div className=\"w-full h-full flex flex-col items-center justify-center bg-[#0e0e0e] gap-3\">
             <div className=\"w-1.5 h-1.5 bg-[#969696] rounded-full animate-bounce\" />
             <span className=\"text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px] uppercase\">Generating perspective...</span>
          </div>
        ) : image.status === 'error' ? (
          <div className=\"w-full h-full flex flex-col items-center justify-center bg-[#0e0e0e] gap-3 border border-red-900/30\">
            <span className=\"text-[11px] font-medium text-red-400 tracking-[0.1px] uppercase\">Generation Failed</span>
          </div>
        ) : image.dataUrl ? (
          <img 
            src={image.dataUrl} 
            alt={image.prompt} 
            className=\"w-full h-full object-cover\"
          />
        ) : null}
      </div>

      {/* Info & Metadata */}
      <div className=\"flex flex-col gap-3 px-1\">
        <div className=\"flex items-start justify-between gap-4\">
          <div className=\"flex flex-col gap-0.5\">
            <span className=\"text-[13px] font-medium text-white\">
              {image.chipLabel}
            </span>
            <span className=\"text-[11px] text-[rgba(255,255,255,0.35)] font-medium uppercase tracking-[0.2px]\">
              {image.modelName} Model
            </span>
          </div>

          <div className=\"flex items-center gap-1\">
            <button 
              onClick={() => onPromote(image)}
              disabled={isLoading}
              title=\"Set as input\"
              className={`flex items-center justify-center w-[34px] h-[34px] transition-all rounded-xl border border-[#595959] bg-transparent ${isLoading ? 'opacity-20' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'}`}
            >
              <ArrowLeft size={16} strokeWidth={1.5} />
            </button>
            <button 
              onClick={() => onReFire(image)}
              disabled={isLoading}
              title=\"Re-run perspective\"
              className={`flex items-center justify-center w-[34px] h-[34px] transition-all rounded-xl border border-[#595959] bg-transparent ${isLoading ? 'opacity-20' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'}`}
            >
              <RefreshCw size={16} strokeWidth={1.5} />
            </button>
            <button 
              onClick={handleDownload}
              disabled={isLoading}
              title=\"Save to grid\"
              className={`flex items-center justify-center w-[34px] h-[34px] transition-all rounded-xl border border-[#595959] bg-transparent ${isLoading ? 'opacity-20' : (isSaved ? 'text-[#969696] bg-white/10' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5')}`}
            >
              {isSaved ? <CheckCircle2 size={16} strokeWidth={1.5} /> : <Download size={16} strokeWidth={1.5} />}
            </button>
            <button 
              onClick={() => onDelete(image.id)}
              title=\"Delete from history\"
              className=\"flex items-center justify-center w-[34px] h-[34px] transition-all rounded-xl border border-[#595959] bg-transparent text-[rgba(218,220,224,0.75)] hover:text-red-400 hover:border-red-900/50 hover:bg-red-500/5\"
            >
              <Trash2 size={16} strokeWidth={1.5} />
            </button>
            <button 
              onClick={() => setShowFullPrompt(!showFullPrompt)}
              className=\"flex items-center justify-center w-[34px] h-[34px] transition-all rounded-xl border border-[#595959] bg-transparent text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5\"
            >
              {showFullPrompt ? <ChevronUp size={16} strokeWidth={1.5} /> : <ChevronDown size={16} strokeWidth={1.5} />}
            </button>
          </div>
        </div>

        {showFullPrompt && (
          <div className=\"animate-in fade-in slide-in-from-top-1 duration-200 p-3 rounded-xl border border-[#595959] bg-[#0e0e0e]/50\">
            <p className=\"text-[rgba(218,220,224,0.75)] text-[11px] leading-relaxed font-medium\">
              <span className=\"text-[rgba(255,255,255,0.35)] uppercase tracking-wider mr-2\">Prompt:</span>
              {image.prompt}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from '@google/genai';

export type ModelType = 'nano-banana' | 'nano-banana-pro';

export const generateAngle = async (
  prompt: string, 
  referenceImageBase64: string, 
  referenceImageMimeType: string,
  model: ModelType = 'nano-banana-pro'
) => {
  const modelName = model === 'nano-banana-pro' ? 'gemini-3.1-flash-image-preview' : 'gemini-2.5-flash-image';

  const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

  const response = await ai.models.generateContent({
    model: modelName,
    contents: {
      parts: [
        {
          inlineData: {
            data: referenceImageBase64,
            mimeType: referenceImageMimeType || 'image/jpeg',
          },
        },
        { text: `give me a new camera angle of this exact scene based on this input: ${prompt}` }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: '16:9'
      }
    }
  });

  const parts = response.candidates?.[0]?.content?.parts;
  if (!parts) throw new Error(\"No response parts received\");

  for (const part of parts) {
    if (part.inlineData) {
      const base64Image = part.inlineData.data;
      return {
        base64Image,
        dataUrl: `data:${part.inlineData.mimeType || 'image/png'};base64,${base64Image}`
      };
    }
  }

  throw new Error(\"No image data found in response\");
};

import {StrictMode} from 'react';
import {createRoot} from 'react-dom/client';
import App from './App.tsx';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { GeneratedImage, AngleChip, SourceImage } from './types';
import { PRESET_ANGLES } from './constants';
import { generateAngle, ModelType } from './services/ai';
import { ImageCard } from './components/ImageCard';
import { ImagePlus, RotateCcw, MonitorUp } from 'lucide-react';

declare global {
  interface Window {
    aistudio?: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const SegmentedToggle: React.FC<{
  value: string; items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className=\"flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent\">
    {items.map((item) => (
      <button key={item.value} type=\"button\" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-3 py-2 rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export default function App() {
  const [sourceImage, setSourceImage] = useState<SourceImage | null>(null);
  const [feed, setFeed] = useState<GeneratedImage[]>([]);
  const [isDraggingOver, setIsDraggingOver] = useState(false);
  const [model, setModel] = useState<ModelType>('nano-banana-pro');
  const [hasApiKey, setHasApiKey] = useState(false);
  const [checkingApiKey, setCheckingApiKey] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        setHasApiKey(true);
      }
      setCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  useEffect(() => {
    const id = 'google-sans-fonts';
    if (!document.getElementById(id)) {
      const link = document.createElement('link');
      link.id = id;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
      document.head.appendChild(link);
    }
  }, []);

  const handleLocalUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target?.result as string;
      const base64 = dataUrl.split(',')[1];
      setSourceImage({
        id: crypto.randomUUID(),
        base64,
        dataUrl,
        mimeType: file.type
      });
    };
    reader.readAsDataURL(file);

    // Reset file input so same file can be selected again
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handlePromoteToSource = useCallback((image: GeneratedImage) => {
    if (image.status !== 'ready' || !image.base64) return;

    setSourceImage({
      id: crypto.randomUUID(),
      base64: image.base64,
      dataUrl: image.dataUrl,
      // Default to image/png if parsing dataUrl fails
      mimeType: image.dataUrl.split(';')[0]?.split(':')[1] || 'image/png'
    });
  }, []);

  const handleDeleteImage = useCallback((id: string) => {
    setFeed(prev => prev.filter(img => img.id !== id));
  }, []);

  const handleFireAngle = useCallback(async (chip: AngleChip, overrideSource?: SourceImage) => {
    const activeSource = overrideSource || sourceImage;
    if (!activeSource) return;

    const id = crypto.randomUUID();
    const activePrompt = chip.defaultPrompt.trim();

    const placeholder: GeneratedImage = {
      id,
      dataUrl: '',
      sourceImageUrl: activeSource.dataUrl,
      prompt: activePrompt,
      chipLabel: `${chip.emoji} ${chip.label}`,
      modelName: model === 'nano-banana-pro' ? 'Pro' : 'Standard',
      timestamp: Date.now(),
      status: 'loading'
    };

    setFeed(prev => [placeholder, ...prev]);

    try {
      const result = await generateAngle(activePrompt, activeSource.base64, activeSource.mimeType, model);
      setFeed(prev => prev.map(img => 
        img.id === id 
          ? { ...img, dataUrl: result.dataUrl, base64: result.base64Image, status: 'ready' as const }
          : img
      ));
    } catch (error: any) {
      console.error(error);
      if (error?.message?.includes('Requested entity was not found') || error?.message?.includes('PERMISSION_DENIED') || error?.status === 403 || error?.message?.includes('403')) {
        setHasApiKey(false);
      }
      setFeed(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'error' as const } : img
      ));
    }
  }, [sourceImage, model]);

  const handleReset = () => {
    setSourceImage(null);
    setFeed([]);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDraggingOver(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (event) => {
          const dataUrl = event.target?.result as string;
          const base64 = dataUrl.split(',')[1];
          setSourceImage({
            id: crypto.randomUUID(),
            base64,
            dataUrl,
            mimeType: file.type
          });
        };
        reader.readAsDataURL(file);
      }
      return;
    }

    try {
      const dataStr = e.dataTransfer.getData('application/json');
      if (dataStr) {
        const imageData = JSON.parse(dataStr);
        handlePromoteToSource(imageData);
      }
    } catch (err) {
      console.error('Failed to parse dropped image data', err);
    }
  };

  if (checkingApiKey) {
    return <div className=\"flex h-screen w-screen bg-[#0e0e0e] items-center justify-center text-[rgba(218,220,224,0.75)] font-medium\">Loading...</div>;
  }

  if (!hasApiKey) {
    return (
      <div className=\"flex h-screen w-screen bg-[#0e0e0e] items-center justify-center text-white p-4 font-sans\">
        <div className=\"flex flex-col max-w-md items-center gap-6 p-8 border border-[#595959] rounded-2xl bg-[#0e0e0e]\">
          <div className=\"flex flex-col gap-2 text-center\">
            <h1 className=\"text-2xl font-semibold tracking-tight text-white mb-2\">API Key Required</h1>
            <p className=\"text-[rgba(218,220,224,0.75)] text-sm leading-relaxed\">
              This app uses high-quality image models that require a paid Google Cloud API key. 
              Please select a key from a Google Cloud project with billing enabled.
            </p>
            <a 
              href=\"https://ai.google.dev/gemini-api/docs/billing\" 
              target=\"_blank\" 
              rel=\"noreferrer\"
              className=\"text-[#8ab4f8] hover:text-[#aecbfa] underline underline-offset-2 text-sm mt-2 w-fit mx-auto transition-colors\"
            >
              Learn more about billing
            </a>
          </div>
          <button 
            onClick={handleSelectKey}
            className=\"flex items-center justify-center h-10 px-8 rounded-xl bg-white text-black font-medium hover:bg-neutral-200 transition-all active:scale-95\"
          >
            Select API Key
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className=\"flex h-screen w-screen bg-[#0e0e0e] text-white font-['Google_Sans_Text',_sans-serif] overflow-hidden\">

      {/* Hidden File Input */}
      <input 
        type=\"file\" 
        ref={fileInputRef} 
        className=\"hidden\" 
        accept=\"image/*\" 
        onChange={handleLocalUpload} 
      />

      {/* Left Panel - Widened to 45% with larger max-width */}
      <aside className=\"w-[45%] min-w-[320px] max-w-[700px] border-r border-[rgba(218,220,224,0.15)] flex flex-col bg-transparent overflow-clip shrink-0\">

        {/* Sidebar Content */}
        <div className=\"flex flex-col gap-[32px] flex-1 overflow-y-auto px-[24px] py-[32px] scrollbar-hide\">

          {/* Source Image Area */}
          <div className=\"flex flex-col gap-3 items-start w-full\">
            <section 
              onDragOver={(e) => { e.preventDefault(); setIsDraggingOver(true); }}
              onDragLeave={() => setIsDraggingOver(false)}
              onDrop={onDrop}
              className={`relative w-full aspect-video flex flex-col items-center justify-center transition-all overflow-hidden border border-[#595959] rounded-xl ${isDraggingOver ? 'bg-white/5 border-white/40' : 'bg-black'}`}
            >
              {sourceImage ? (
                <img src={sourceImage.dataUrl} className=\"w-full h-full object-contain\" alt=\"Source\" />
              ) : (
                <div className=\"text-center p-4\">
                  <div className=\"w-8 h-8 flex items-center justify-center mx-auto mb-2 text-[rgba(218,220,224,0.35)]\">
                    <ImagePlus size={20} strokeWidth={1.5} />
                  </div>
                  <span className=\"text-[11px] text-[rgba(218,220,224,0.5)] font-medium\">
                    Drag and drop or use buttons below
                  </span>
                </div>
              )}
            </section>

            {/* Input Action Buttons */}
            <div className=\"flex gap-2 w-full\">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className=\"flex-1 flex items-center justify-center gap-2 h-[36px] px-3 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5 transition-all\"
              >
                <MonitorUp size={16} strokeWidth={1.5} />
                <span>UPLOAD FROM DEVICE</span>
              </button>
            </div>
          </div>

          {/* Shot Angles (Chips) */}
          <div className=\"flex flex-wrap gap-2\">
            {PRESET_ANGLES.map((chip) => (
              <button
                key={chip.id}
                onClick={() => handleFireAngle(chip)}
                disabled={!sourceImage}
                className={`flex items-center gap-1.5 h-[36px] px-4 py-2 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-white hover:bg-white/5 active:bg-white/10 transition-all select-none disabled:opacity-20 disabled:cursor-not-allowed`}
              >
                <span className=\"text-sm\">{chip.emoji}</span>
                <span className=\"tracking-[0.1px]\">{chip.label}</span>
              </button>
            ))}
          </div>

          {/* Configuration */}
          <div className=\"flex flex-col gap-1.5 w-full\">
            <SegmentedToggle 
              value={model}
              onChange={(v) => setModel(v as ModelType)}
              items={[
                { value: 'nano-banana', label: 'Standard' },
                { value: 'nano-banana-pro', label: 'Pro' }
              ]}
            />
          </div>
        </div>

        {/* Pinned Bottom Action */}
        <div className=\"px-[24px] py-[16px] border-t border-[rgba(218,220,224,0.15)] bg-transparent\">
          <button 
            onClick={handleReset}
            className=\"flex items-center justify-center gap-2 w-full h-[36px] rounded-xl border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-[rgba(218,220,224,0.75)] hover:text-red-400 transition-all cursor-pointer select-none\"
          >
            <RotateCcw size={16} strokeWidth={1.5} />
            <span>RESET SESSION</span>
          </button>
        </div>
      </aside>

      {/* Results Feed */}
      <main className=\"flex-1 overflow-y-auto bg-[#0e0e0e] dark-scrollbar p-10\">
        <div className=\"grid grid-cols-1 gap-12 max-w-3xl mx-auto pb-20\">
          {feed.map((image) => (
            <ImageCard 
              key={image.id} 
              image={image} 
              onPromote={handlePromoteToSource}
              onDelete={handleDeleteImage}
              onReFire={() => {
                const preset = PRESET_ANGLES.find(p => `${p.emoji} ${p.label}` === image.chipLabel);
                if (preset) {
                  const sourceOverride: SourceImage | undefined = image.sourceImageUrl ? {
                    id: crypto.randomUUID(),
                    dataUrl: image.sourceImageUrl,
                    base64: image.sourceImageUrl.split(',')[1] || '',
                    mimeType: image.sourceImageUrl.split(';')[0]?.split(':')[1] || 'image/png'
                  } : undefined;

                  if (sourceOverride && sourceOverride.dataUrl !== sourceImage?.dataUrl) {
                    setSourceImage(sourceOverride);
                  }
                  handleFireAngle(preset, sourceOverride);
                }
              }}
            />
          ))}
        </div>
      </main>

      <style>{`
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }

        * {
          letter-spacing: 0.1px;
        }
      `}</style>
    </div>
  );
}

export interface GeneratedImage {
  id: string;
  mediaId: string;
  base64: string;
  mimeType: string;
  sourceMediaId?: string;
  prompt: string;
  chipLabel: string;
  modelName: string;
  timestamp: number;
  status: 'loading' | 'ready' | 'error';
}

export interface AngleChip {
  id: string;
  label: string;
  emoji: string;
  defaultPrompt: string;
}

export interface SourceImage {
  mediaId: string;
  base64: string;
  dataUrl: string;
  mimeType: string;
}

