import { Flow } from 'flow-sdk';

export type ModelType = 'nano-banana-2' | 'nano-banana-pro';

export const generateAngle = async (
  prompt: string, 
  referenceImageMediaId: string, 
  model: ModelType = 'nano-banana-pro'
) => {
  // Use the exact model names from the system documentation
  const modelDisplayName = model === 'nano-banana-pro' ? 'Nano Banana Pro' : 'Nano Banana 2';

  const result = await Flow.generate.image({
    prompt: `A cinematic new camera angle of this scene: ${prompt}`,
    referenceImageMediaIds: [referenceImageMediaId],
    aspectRatio: '16:9',
    modelDisplayName
  });

  return {
    base64: result.base64,
    mimeType: result.mimeType,
    mediaId: result.mediaId,
    dataUrl: `data:${result.mimeType};base64,${result.base64}`
  };
};

import React, { useState } from 'react';
import { GeneratedImage } from '../types';
import { Flow } from 'flow-sdk';

interface ImageCardProps {
  image: GeneratedImage;
  onReFire: (image: GeneratedImage) => void;
  onPromote: (image: GeneratedImage) => void;
  onDelete: (id: string) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ image, onReFire, onPromote, onDelete }) => {
  const [showFullPrompt, setShowFullPrompt] = useState(false);
  const [saveState, setSaveState] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  const handleSaveToGallery = async () => {
    if (image.status !== 'ready' || !image.base64) return;

    setSaveState('saving');
    try {
      await Flow.save({
        base64: image.base64,
        mimeType: image.mimeType as 'image/png' | 'image/jpeg',
        name: `Shot - ${image.chipLabel}`
      });
      setSaveState('saved');
      setTimeout(() => setSaveState('idle'), 2000);
    } catch (err) {
      console.error('Failed to save to gallery', err);
      setSaveState('error');
      setTimeout(() => setSaveState('idle'), 3000);
    }
  };

  const onDragStart = (e: React.DragEvent) => {
    if (image.status !== 'ready') return;
    e.dataTransfer.setData('application/json', JSON.stringify(image));
    e.dataTransfer.effectAllowed = 'move';
  };

  const isLoading = image.status === 'loading';
  const isSaving = saveState === 'saving';
  const isSaved = saveState === 'saved';
  const hasError = saveState === 'error';

  return (
    <div 
      className={`flex flex-col w-full group ${image.status === 'ready' ? 'cursor-grab active:cursor-grabbing' : ''}`}
      draggable={image.status === 'ready'}
      onDragStart={onDragStart}
    >
      <div className="relative aspect-video border border-[rgba(218,220,224,0.15)] bg-[#000000] rounded-2xl overflow-hidden mb-4 shadow-sm transition-all">
        {isLoading ? (
          <div className="w-full h-full flex flex-col items-center justify-center bg-[#000000] gap-3">
             <div className="flex gap-1">
               <div className="w-1 h-1 bg-[#969696] rounded-full animate-bounce [animation-delay:-0.3s]" />
               <div className="w-1 h-1 bg-[#969696] rounded-full animate-bounce [animation-delay:-0.15s]" />
               <div className="w-1 h-1 bg-[#969696] rounded-full animate-bounce" />
             </div>
             <span className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px] uppercase">Generating ...</span>
          </div>
        ) : image.status === 'error' ? (
          <div className="w-full h-full flex flex-col items-center justify-center bg-[#000000] gap-3 border border-red-900/30">
            <span className="text-[11px] font-medium text-red-400 tracking-[0.1px] uppercase">Generation Failed</span>
          </div>
        ) : image.base64 ? (
          <img 
            src={`data:${image.mimeType};base64,${image.base64}`} 
            alt={image.prompt} 
            className="w-full h-full object-cover"
          />
        ) : null}
      </div>

      <div className="flex flex-col gap-3 px-1">
        <div className="flex items-start justify-between gap-4">
          <div className="flex flex-col gap-0.5">
            <span className="text-[13px] font-medium text-white">
              {image.chipLabel}
            </span>
            <span className="text-[11px] text-[rgba(255,255,255,0.35)] font-medium uppercase tracking-[0.2px]">
              {image.modelName}
            </span>
          </div>

          <div className="flex items-center gap-1">
            {/* Explore Button */}
            <button 
              onClick={() => onPromote(image)}
              disabled={isLoading}
              title="Set as input"
              className={`flex items-center gap-1.5 h-[34px] px-2 transition-all bg-transparent ${isLoading ? 'opacity-20' : 'text-[rgba(218,220,224,0.75)] hover:text-white'}`}
            >
              <span className="material-symbols-outlined text-[20px]">add_box</span>
              <span className="text-[11px] font-medium uppercase tracking-[0.5px]">Explore</span>
            </button>

            {/* Separator Keyline */}
            <div className="w-[1px] h-[16px] bg-[rgba(218,220,224,0.15)] mx-1" />

            <button 
              onClick={() => onReFire(image)}
              disabled={isLoading}
              title="Re-run perspective"
              className={`flex items-center justify-center w-[34px] h-[34px] transition-all bg-transparent ${isLoading ? 'opacity-20' : 'text-[rgba(218,220,224,0.75)] hover:text-white'}`}
            >
              <span className="material-symbols-outlined text-[20px]">refresh</span>
            </button>
            <button 
              onClick={handleSaveToGallery}
              disabled={isLoading || isSaving}
              title={hasError ? "Save failed" : isSaved ? "Saved to gallery" : "Save to gallery"}
              className={`flex items-center justify-center w-[34px] h-[34px] transition-all bg-transparent ${
                isLoading || isSaving ? 'opacity-20' : 
                hasError ? 'text-red-400' :
                isSaved ? 'text-[#969696]' : 
                'text-[rgba(218,220,224,0.75)] hover:text-white'
              }`}
            >
              {isSaving ? (
                <span className="material-symbols-outlined text-[20px] animate-spin">sync</span>
              ) : (
                <span className="material-symbols-outlined text-[20px]">
                  {hasError ? 'error' : isSaved ? 'check_circle' : 'download'}
                </span>
              )}
            </button>
            <button 
              onClick={() => onDelete(image.id)}
              title="Delete from history"
              className="flex items-center justify-center w-[34px] h-[34px] transition-all bg-transparent text-[rgba(218,220,224,0.75)] hover:text-red-400"
            >
              <span className="material-symbols-outlined text-[20px]">delete</span>
            </button>
            <button 
              onClick={() => setShowFullPrompt(!showFullPrompt)}
              className="flex items-center justify-center w-[34px] h-[34px] transition-all bg-transparent text-[rgba(218,220,224,0.75)] hover:text-white"
            >
              <span className="material-symbols-outlined text-[20px]">{showFullPrompt ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}</span>
            </button>
          </div>
        </div>

        {showFullPrompt && (
          <div className="animate-in fade-in slide-in-from-top-1 duration-200 pt-3 border-t border-[rgba(218,220,224,0.15)] mt-1">
            <p className="text-[rgba(218,220,224,0.75)] text-[11px] leading-relaxed font-medium select-text">
              Prompt: {image.prompt}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { GeneratedImage, AngleChip, SourceImage } from './types';
import { PRESET_ANGLES } from './constants';
import { generateAngle, ModelType } from './services/ai';
import { ImageCard } from './components/ImageCard';
import { Flow } from 'flow-sdk';

const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2 mb-1.5">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const SegmentedToggle: React.FC<{
  value: string; items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-2 py-2 rounded-xl text-[11px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export default function App() {
  const [sourceImage, setSourceImage] = useState<SourceImage | null>(null);
  const [feed, setFeed] = useState<GeneratedImage[]>([]);
  const [isDraggingOver, setIsDraggingOver] = useState(false);
  const [model, setModel] = useState<ModelType>('nano-banana-2');

  useEffect(() => {
    const fontId = 'google-design-system-fonts';
    if (!document.getElementById(fontId)) {
      const link = document.createElement('link');
      link.id = fontId;
      link.rel = 'stylesheet';
