      document.head.appendChild(link);
    }

    const styleId = 'flow-applet-global-css';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        @utility scrollbar-hide {
          -ms-overflow-style: none;
          scrollbar-width: none;
          &::-webkit-scrollbar { display: none; }
        }
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }
        html, body, #root {
          margin: 0; padding: 0; width: 100%; height: 100%;
          background: #000000;
          font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;
          -webkit-font-smoothing: antialiased;
          -moz-osx-font-smoothing: grayscale;
          letter-spacing: 0.1px;
        }
        .material-symbols-outlined {
          font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
          display: inline-block;
          line-height: 1;
          text-transform: none;
          letter-spacing: normal;
          word-wrap: normal;
          white-space: nowrap;
          direction: ltr;
        }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const handleMediaSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      setSourceImage({
        mediaId: media.mediaId,
        base64: media.base64,
        dataUrl: `data:${media.mimeType};base64,${media.base64}`,
        mimeType: media.mimeType
      });
    } catch (err) {
      console.error('Failed to select media', err);
    }
  };

  const handlePromoteToSource = useCallback((image: GeneratedImage) => {
    if (image.status !== 'ready' || !image.base64) return;
    setSourceImage({
      mediaId: image.mediaId,
      base64: image.base64,
      dataUrl: `data:${image.mimeType};base64,${image.base64}`,
      mimeType: image.mimeType
    });
  }, []);

  const handleDeleteImage = useCallback((id: string) => {
    setFeed(prev => prev.filter(img => img.id !== id));
  }, []);

  const handleFireAngle = useCallback(async (chip: AngleChip, overrideSource?: SourceImage) => {
    const activeSource = overrideSource || sourceImage;
    if (!activeSource) return;

    const id = crypto.randomUUID();
    const activePrompt = chip.defaultPrompt.trim();

    const placeholder: GeneratedImage = {
      id,
      mediaId: '',
      base64: '',
      mimeType: 'image/png',
      sourceMediaId: activeSource.mediaId,
      prompt: activePrompt,
      chipLabel: `${chip.emoji} ${chip.label}`,
      modelName: model === 'nano-banana-pro' ? 'Pro' : 'Fast',
      timestamp: Date.now(),
      status: 'loading'
    };

    setFeed(prev => [placeholder, ...prev]);

    try {
      const result = await generateAngle(activePrompt, activeSource.mediaId, model);
      setFeed(prev => prev.map(img => 
        img.id === id 
          ? { 
              ...img, 
              mediaId: result.mediaId,
              base64: result.base64, 
              mimeType: result.mimeType,
              status: 'ready' as const 
            }
          : img
      ));
    } catch (error: any) {
      console.error(error);
      setFeed(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'error' as const } : img
      ));
    }
  }, [sourceImage, model]);

  const handleReset = () => {
    setSourceImage(null);
    setFeed([]);
  };

  const onDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDraggingOver(false);
    try {
      const dataStr = e.dataTransfer.getData('application/json');
      if (dataStr) {
        const imageData = JSON.parse(dataStr);
        handlePromoteToSource(imageData);
      }
    } catch (err) {
      console.error('Failed to parse dropped image data', err);
    }
  };

  // Chips filtered by cluster
  const perspectiveChips = PRESET_ANGLES.filter(c => ['birds-eye', 'side-view', 'back-view'].includes(c.id));
  const panChips = PRESET_ANGLES.filter(c => ['pan-left', 'pan-right', 'pan-up', 'pan-down'].includes(c.id));
  const zoomChips = PRESET_ANGLES.filter(c => ['zoom-in', 'zoom-out', 'extreme-detail', 'surprise-me'].includes(c.id));

  return (
    <div className="flex h-screen w-screen bg-[#000000] text-white font-['Google_Sans_Text',_sans-serif] overflow-hidden">
      <aside className="w-[45%] min-w-[320px] max-w-[700px] border-r border-[rgba(218,220,224,0.15)] flex flex-col bg-transparent overflow-clip shrink-0">
        <div className="flex flex-col gap-[24px] flex-1 overflow-y-auto px-[24px] py-[32px] scrollbar-hide">
          {/* Source Image Area */}
          <div className="flex flex-col gap-3 items-start w-full mb-2">
            <section 
              onDragOver={(e) => { e.preventDefault(); setIsDraggingOver(true); }}
              onDragLeave={() => setIsDraggingOver(false)}
              onDrop={onDrop}
              className={`relative w-full aspect-video flex flex-col items-center justify-center transition-all overflow-hidden border border-[#595959] rounded-xl ${isDraggingOver ? 'bg-white/5 border-white/40' : 'bg-[#000000]'}`}
            >
              {sourceImage ? (
                <img src={sourceImage.dataUrl} className="w-full h-full object-contain" alt="Source" />
              ) : (
                <div className="text-center p-4">
                  <span className="text-[11px] text-[rgba(218,220,224,0.5)] font-medium">
                    Select an image to start exploring angles
                  </span>
                </div>
              )}
            </section>
            <div className="flex gap-2 w-full">
              <button 
                onClick={handleMediaSelect}
                className="flex-1 flex items-center justify-center gap-2 h-[36px] px-3 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5 transition-all"
              >
                <span className="material-symbols-outlined text-[18px]">grid_view</span>
                <span>SELECT IMAGE</span>
              </button>
            </div>
          </div>

          {/* Perspective Cluster */}
          <div className="flex flex-col w-full">
            <SectionLabel>Perspective</SectionLabel>
            <div className="flex flex-wrap gap-2">
              {perspectiveChips.map(chip => (
                <button key={chip.id} onClick={() => handleFireAngle(chip)} disabled={!sourceImage}
                  className="flex items-center gap-1.5 h-[36px] px-4 py-2 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-white hover:bg-white/5 active:bg-white/10 transition-all select-none disabled:opacity-20 disabled:cursor-not-allowed">
                  <span className="text-sm">{chip.emoji}</span>
                  <span className="tracking-[0.1px] whitespace-nowrap">{chip.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Pan Cluster */}
          <div className="flex flex-col w-full">
            <SectionLabel>Pan</SectionLabel>
            <div className="flex flex-wrap gap-1.5">
              {panChips.map(chip => (
                <button key={chip.id} onClick={() => handleFireAngle(chip)} disabled={!sourceImage}
                  className="flex-1 flex items-center justify-center gap-1.5 h-[36px] px-2 py-2 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-white hover:bg-white/5 active:bg-white/10 transition-all select-none disabled:opacity-20 disabled:cursor-not-allowed">
                  <span className="text-sm">{chip.emoji}</span>
                  <span className="tracking-[0.1px] whitespace-nowrap">{chip.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Zoom Cluster */}
          <div className="flex flex-col w-full">
            <SectionLabel>Zoom</SectionLabel>
            <div className="flex flex-wrap gap-2">
              {zoomChips.map(chip => (
                <button key={chip.id} onClick={() => handleFireAngle(chip)} disabled={!sourceImage}
                  className="flex items-center gap-1.5 h-[36px] px-4 py-2 rounded-xl border border-[#595959] bg-transparent text-[12px] font-medium text-white hover:bg-white/5 active:bg-white/10 transition-all select-none disabled:opacity-20 disabled:cursor-not-allowed">
                  <span className="text-sm">{chip.emoji}</span>
                  <span className="tracking-[0.1px] whitespace-nowrap">{chip.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Pinned Bottom Area */}
        <div className="px-[24px] py-[16px] border-t border-[rgba(218,220,224,0.15)] bg-transparent flex items-center justify-between gap-3">
          <button 
            onClick={handleReset}
            className="flex flex-1 items-center justify-center gap-2 h-[34px] px-3 rounded-xl border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[11px] font-medium text-[rgba(218,220,224,0.75)] hover:text-red-400 transition-all cursor-pointer select-none"
          >
            <span className="material-symbols-outlined text-[18px]">restart_alt</span>
            <span className="uppercase tracking-widest">RESET</span>
          </button>
          <div className="w-[110px] shrink-0">
            <SegmentedToggle 
              value={model}
              onChange={(v) => setModel(v as ModelType)}
              items={[
                { value: 'nano-banana-2', label: 'Fast' },
                { value: 'nano-banana-pro', label: 'Pro' }
              ]}
            />
          </div>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto bg-[#000000] dark-scrollbar p-10">
        <div className="grid grid-cols-1 gap-12 max-w-3xl mx-auto pb-20">
          {feed.map((image) => (
            <ImageCard 
              key={image.id} 
              image={image} 
              onPromote={handlePromoteToSource}
              onDelete={handleDeleteImage}
              onReFire={() => {
                const preset = PRESET_ANGLES.find(p => `${p.emoji} ${p.label}` === image.chipLabel);
                if (preset) {
                  handleFireAngle(preset);
                }
              }}
            />
          ))}
        </div>
      </main>
    </div>
  );
}
